-- Eva's read model. GENERATED by scripts/gen-eva-view.py from supabase/eva_question_map.json. Do not edit by hand.
-- One row per completed application, one column per question, named like QUESTION_MAP in intake_pipeline.py.

-- Text value of one answer. A list of options (checkboxes) is joined with '; '.
create or replace function intake_text(answers jsonb, k text) returns text
language sql immutable as $$
  select case jsonb_typeof(answers -> k)
    when 'array'  then (select coalesce(string_agg(x, '; '), '') from jsonb_array_elements_text(answers -> k) x)
    else coalesce(answers ->> k, '')
  end
$$;

create or replace view intake_rows with (security_invoker = true) as
select
  a.application_id,
  date_trunc('second', a.finalized_at) as created_at,
  date_trunc('second', a.finalized_at) as "Timestamp",
  intake_text(a.answers, '0.1') as "Q01_Readiness_Checklist",
  intake_text(a.answers, '0.2') as "Q02_Eligibility_Checklist",
  intake_text(a.answers, 'A1') as "A1_Applicant_Type",
  intake_text(a.answers, 'A1b') as "A1b_Org_Type",
  intake_text(a.answers, 'A2') as "A2_Time_Operating",
  intake_text(a.answers, 'A3') as "A3_Prior_Grant",
  intake_text(a.answers, 'A4') as "A4_Requested_Amount",
  intake_text(a.answers, 'B1') as "B1_Legal_Name",
  intake_text(a.answers, 'B2') as "B2_Country",
  intake_text(a.answers, 'B3') as "B3_Legal_Rep_Name",
  intake_text(a.answers, 'B4') as "B4_Address",
  intake_text(a.answers, 'B5') as "B5_Annual_Budget",
  intake_text(a.answers, 'B6') as "B6_Website",
  intake_text(a.answers, 'B7') as "B7_FTE_Staff",
  intake_text(a.answers, 'B8') as "B8_Registration_Number",
  coalesce((select 'storage:' || f.storage_path from application_files f where f.application_id = a.application_id and f.question = 'C1'), '') as "C1_Registration_Doc",
  coalesce((select 'storage:' || f.storage_path from application_files f where f.application_id = a.application_id and f.question = 'C2'), '') as "C2_Tax_Form",
  intake_text(a.answers, 'C3') as "C3_Person_Registration_Info",
  intake_text(a.answers, 'D1') as "D1_Primary_Contact",
  intake_text(a.answers, 'D2') as "D2_Contact_Authorized",
  intake_text(a.answers, 'D3') as "D3_Signer",
  intake_text(a.answers, 'D4') as "D4_Copy_Email",
  intake_text(a.answers, 'E1') as "E1_Project_Title_Summary",
  intake_text(a.answers, 'E2') as "E2_Dates",
  intake_text(a.answers, 'E3') as "E3_Location",
  intake_text(a.answers, 'E4') as "E4_Economic_Barrier",
  intake_text(a.answers, 'E5') as "E5_Participant_Count",
  intake_text(a.answers, 'E6') as "E6_Participant_Profile",
  intake_text(a.answers, 'E7') as "E7_Primary_Result",
  intake_text(a.answers, 'E8') as "E8_Application_Partner",
  intake_text(a.answers, 'E9') as "E9_Bitcoin_Uses",
  intake_text(a.answers, 'E10') as "E10_Milestones",
  intake_text(a.answers, 'E11') as "E11_Risks",
  intake_text(a.answers, 'E12') as "E12_Target_Stage",
  intake_text(a.answers, 'E13') as "E13_Value_Circulation",
  intake_text(a.answers, 'F1') as "F1_Main_Measure",
  intake_text(a.answers, 'F2') as "F2_Baseline",
  intake_text(a.answers, 'F3') as "F3_Target_12mo",
  intake_text(a.answers, 'F4') as "F4_Verification",
  intake_text(a.answers, 'F5') as "F5_Prior_Results",
  intake_text(a.answers, 'G1') as "G1_Total_Budget",
  intake_text(a.answers, 'G2') as "G2_Requested_Amount",
  intake_text(a.answers, 'G3') as "G3_Other_Funders",
  intake_text(a.answers, 'G4') as "G4_Budget_By_Category",
  intake_text(a.answers, 'G5') as "G5_Fund_Uses",
  intake_text(a.answers, 'G7') as "G7_Continuity",
  intake_text(a.answers, 'G8') as "G8_Payment_Method",
  intake_text(a.answers, 'H1') as "H1_Team_Capacity",
  intake_text(a.answers, 'H2') as "H2_Support_Needs",
  intake_text(a.answers, 'I1') as "I1_Children_Involved",
  intake_text(a.answers, 'I2') as "I2_Safeguarding_Policy",
  intake_text(a.answers, 'I3') as "I3_Participant_Data",
  intake_text(a.answers, 'J1') as "J1_Renewal_Results",
  intake_text(a.answers, 'J2') as "J2_Stage_Reached_2026",
  coalesce((select 'storage:' || f.storage_path from application_files f where f.application_id = a.application_id and f.question = 'J3'), '') as "J3_Report_2026",
  intake_text(a.answers, 'K1') as "K1_Disclosures",
  intake_text(a.answers, 'K2') as "K2_Disclosure_Details",
  intake_text(a.answers, 'K3') as "K3_Certification",
  intake_text(a.answers, 'K4') as "K4_Data_Consent",
  intake_text(a.answers, 'K5') as "K5_Submitter"
from applications a
where a.status = 'complete'
  and a.finalized_at <= now() - interval '2 minutes';   -- settle delay: nothing can arrive "late" behind the watermark

-- Lock everything down. Supabase gives anon/authenticated access to new objects in `public` by default;
-- the publishable key must never read applications, files, the counter or this view.
revoke all on applications, application_files, rate_events, intake_rows from anon, authenticated;
revoke execute on function next_application_id() from public, anon, authenticated;
revoke execute on function intake_text(jsonb, text) from public, anon, authenticated;
grant  execute on function next_application_id() to service_role;
grant  execute on function intake_text(jsonb, text) to service_role;
grant  select on intake_rows to service_role;
revoke all on sequence application_seq from anon, authenticated;
grant  usage, select on sequence application_seq to service_role;
